 const dense=['dense','repeat'].includes(pattern),pages=[...new Set(study.round.map(a=>Math.floor(a/pageSize)))];$('#tc-array').className='tc-array '+(dense?'is-dense':'is-sparse');
 text('#tc-layout-caption',dense?'每格 4 B；灰格不属于该数组。':'按页归组，仅列出访问的位置。');
 $('#tc-array').innerHTML=pages.map(vpn=>{const addresses=dense?Array.from({length:pageSize/4},(_,i)=>vpn*pageSize+i*4):study.round.filter(a=>Math.floor(a/pageSize)===vpn);return `<div class="tc-page-group" data-group-vpn="${vpn}"><h4>页 ${vpn}<small>VA ${vpn*pageSize}–${(vpn+1)*pageSize-1}</small></h4><div class="tc-elements" style="--cells:${dense?Math.min(4,pageSize/4):1}">${addresses.map(a=>{const j=study.round.indexOf(a);if(j<0)return '<span class="tc-other" aria-label="数组以外的 4 字节"></span>';const f=byAddress.get(a),current=s?.address===a;return `<button type="button" data-element="${j}" data-address="${a}" aria-pressed="${current}" aria-label="第 ${j+1} 个位置，VA ${a}${f?f.firstHit?'，TLB 命中':'，TLB 未命中':'，尚未读取'}" class="${f?f.firstHit?'is-hit':'is-miss':'is-wait'}"><b>${dense?'a['+j+']':'位置 '+(j+1)}</b><span>${a}</span><small>${f?f.firstHit?'命中':'未命中':'待读取'}</small></button>`;}).join('')}</div></div>`;}).join('');
 $('#tc-cache').innerHTML=cacheHTML(s?.entries??[],capacity,s?.vpn);text('#tc-replay',count?`逐步查看第 ${count} 次访问 →`:'逐步查看首次访问 →');
