 let title='同页访问复用映射，减少查表',reason=`这 ${study.round.length} 次读取涉及 ${study.activePages} 个页。每页第一次访问要查表；后续是否命中，还取决于映射有没有被替换。`;
 if(pattern==='repeat'){const second=study.lru.completed.slice(study.round.length,count),h=second.filter(f=>f.firstHit).length;title='再次使用，还要看映射是否留在 TLB';reason=count>study.round.length?`第二遍已读取 ${second.length} 次，其中 ${h} 次命中。${capacity>=study.activePages?'容量足够保存这些页的映射，第二遍可以全部命中。':'容量放不下全部映射；重新访问的页可能已经被替换。'}`:`第一遍中的同页访问体现空间局部性；第二遍复用已有映射，体现时间局部性。当前需要 ${study.activePages} 条映射，容量为 ${capacity} 条。`;}
 else if(pattern==='stride'){title='读取数量相同，涉及的页却更多';reason=`这些位置各在不同页。第一次遍历 ${study.activePages} 页，每页都要查表；相邻元素的映射无法复用。`;}
 else if(pattern==='cycle'){title=capacity>=study.activePages?'映射能全部保留，后续循环可以命中':'再次使用之前，映射已被 LRU 替换';reason=capacity>=study.activePages?`首次访问 ${study.activePages} 个页后，映射都能留在 ${capacity} 个槽中。后续读取复用这些映射。`:`循环涉及 ${study.activePages} 页，容量只有 ${capacity} 条。每次重访前，中间已经使用了其他 ${study.activePages-1} 页；按本例 LRU 顺序，所需条目已被替换。`;}
 if(pattern==='cycle'&&pageSize===32&&capacity===1){title='同页位置可复用，跨页循环仍要重新查表';reason='四个位置落在两页。每页连续读取两个位置，第二次可以命中；但只有一个槽，切换到另一页时就会替换旧映射。';}
 else if(pattern==='dense'&&count===study.accesses.length){title=`${count} 次读取，只查了 ${s.tableReads} 次页表`;reason=`命中 ${s.hits} 次、未命中 ${s.misses} 次。同一页内的不同元素共用页号映射，目标数据仍分别读取 ${count} 次。`;}
 text('#tc-conclusion-title',title);text('#tc-conclusion-text',reason);$('#tc-position').max=study.accesses.length;$('#tc-position').value=count;
 text('#tc-settings-summary',`页大小 ${pageSize} B · ${capacity} 条映射最多覆盖 ${capacity*pageSize} B`);text('#tc-coverage',`${capacity} 条 × ${pageSize} B = ${capacity*pageSize} B。当前访问涉及 ${study.activePages} 个页；覆盖量是能保存的映射范围，不保证任意访问分布都命中。`);press('[data-page-size]',pageSize,'pageSize');press('[data-pattern]',pattern,'pattern');
