 $('#tc-context-groups').innerHTML=['flush','asid'].map(mode=>{const g=s.groups[mode];return `<section class="tc-context-policy" data-context-mode="${mode}"><h3>${mode==='flush'?'切换时清空':'同时匹配 ASID 与页号'}</h3><p class="tc-note">${mode==='flush'?'旧条目失效，后续重新查表。':`当前 ASID ${r.asid} · 查询页 10`}</p><div class="tc-context-cache">${Array.from({length:2},(_,i)=>{const e=g.entries[i],match=e?.valid&&e.owner===r.owner;return `<div class="tc-context-entry ${e&&!e.valid?'is-invalid':''} ${!pending&&match?'is-current':''}" ${e?`data-owner="${e.owner}" data-valid="${e.valid}" data-pfn="${e.pfn}"`:''}><small>${e?mode==='asid'?`ASID ${e.asid}`:`来自 ${e.owner}`:'空槽'}</small><strong>${e?`页 ${e.vpn} → 框 ${e.pfn}`:'尚无映射'}</strong><span>${e?!e.valid?'已失效':mode==='asid'&&e.asid!==r.asid?'其他地址空间，不能匹配':'可用':'等待填入'}</span></div>`;}).join('')}</div><p class="tc-context-pa">${pending?'本次尚未生成地址':`PA ${g.physical} · ${s.phase==='access'?'读取完成':'尚未读取'}`}</p><dl class="tc-metrics">${metric('累计查表',g.tableReads)+metric('完成读取',g.targets)}</dl></section>`;}).join('');
 text('#tc-context-result',contextAt===contexts.length-1?'同样完成 3 次读取：清空组查表 3 次，ASID 组查表 2 次。保留映射减少了重新填入的开销。':'两组只改变缓存转换的管理方式，页表映射与物理页面都保持不变。');$$('[data-context-request]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.contextRequest)===s.index)));
