const cc=controller('context',()=>contexts.length-1,()=>contextAt,n=>{contextAt=n;renderContext();});
$$('[data-pattern]').forEach(b=>b.addEventListener('click',()=>{pattern=b.dataset.pattern;resetStudy();}));$('#tc-capacity').addEventListener('change',()=>{capacity=Number($('#tc-capacity').value);resetStudy();});$$('[data-page-size]').forEach(b=>b.addEventListener('click',()=>{pageSize=Number(b.dataset.pageSize);resetStudy();}));$('#tc-position').addEventListener('input',()=>sc.seek(Number($('#tc-position').value)));$('#tc-round').addEventListener('change',()=>sc.seek(Number($('#tc-round').value)*study.round.length+1));
