$('#tc-close').addEventListener('click',()=>$('#tc-walk').close());$('#tc-walk').addEventListener('cancel',()=>pauseAll());$('#tc-walk').addEventListener('close',()=>{pauseAll();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});});$$('[data-handler]').forEach(b=>b.addEventListener('click',()=>{pauseAll();handler=b.dataset.handler;rebuildWalk();}));
$('#tc-walk-steps').addEventListener('click',e=>{const b=e.target.closest('[data-walk-step]');if(!b)return;wc.seek(Number(b.dataset.walkStep));$('[data-walk-step="'+walkAt+'"]').focus({preventScroll:true});});$('#tc-walk-steps').addEventListener('keydown',e=>{if(!e.target.matches('[data-walk-step]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();wc.seek(e.key==='Home'?0:e.key==='End'?walkFrames.length-1:walkAt+(e.key==='ArrowRight'?1:-1));$('[data-walk-step="'+walkAt+'"]').focus({preventScroll:true});});
