$$('summary').forEach(s=>s.addEventListener('click',pauseAll));$$('details').forEach(d=>d.addEventListener('toggle',pauseAll));document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseAll();});window.addEventListener('pagehide',pauseAll);
